/*
* Safeguarding test for requirement "bigint-data-handling":
* mirrors upstream apache/echarts PR #19847
* ("fix: detectValue & parseDataValue not crashing with BigInt").
*/

import { parseDataValue } from '../src/data/helper/dataValueHelper';

describe('bigint-data-handling', function () {

    it('parseDataValue does not crash with BigInt values', function () {
        expect(function () {
            parseDataValue(10n as any, { type: 'number' });
        }).not.toThrow();
        expect(parseDataValue(10n as any, { type: 'number' })).toEqual(10);
    });

    it('parseDataValue keeps existing behavior for other values', function () {
        expect(parseDataValue(' 123 ' as any, { type: 'number' })).toEqual(123);
        expect(parseDataValue('-' as any, { type: 'number' })).toBeNaN();
        expect(parseDataValue(null as any, { type: 'number' })).toBeNaN();
        expect(parseDataValue('' as any, { type: 'number' })).toBeNaN();
        expect(parseDataValue({} as any, { type: 'number' })).toBeNaN();
        expect(parseDataValue('abc' as any, { type: 'ordinal' })).toEqual('abc');
    });

});

